function createDriveHelpers(deadline){
const sleep = (ms) => new Promise(resolve => setTimeout(resolve, ms));

async function driveFetch(url, options = {}) {
  let lastResponse = null;
  let lastError = null;
  for (let attempt = 0; attempt < DRIVE_RETRY_ATTEMPTS; attempt++) {
    try {
      const remaining=deadline-Date.now();if(remaining<1000)throw new Error('BACKUP_CHUNK_DEADLINE');
      const parsed=new URL(url);
      if(parsed.protocol!=='https:'||parsed.hostname!=='www.googleapis.com'||parsed.username||parsed.password||parsed.port)throw new Error('BACKUP_DRIVE_ORIGIN_DENIED');
      const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),Math.min(25000,remaining));
      let response;
      try{const raw=await fetch(url,{...options,redirect:'manual',signal:controller.signal});
        const bytes=await boundedBackupBody(raw,MAX_BACKUP_FILE_BYTES,controller.signal);
        response=new Response([204,205,304].includes(raw.status)?null:bytes,{status:raw.status,headers:raw.headers});
      }finally{clearTimeout(timer);}
      if(response.status>=300&&response.status<400)throw new Error('BACKUP_DRIVE_REDIRECT_DENIED');
      lastResponse = response;
      if (response.status !== 429 && (response.status < 500 || String(options.method||'GET').toUpperCase()!=='GET')) return response;
      if (attempt === DRIVE_RETRY_ATTEMPTS - 1) return response;
      const retryAfter = Number(response.headers.get('retry-after') || 0);
      const delay = retryAfter > 0 ? retryAfter * 1000 : 400 * (2 ** attempt) + Math.floor(Math.random() * 200);
      await sleep(Math.min(delay, 5000));
    } catch (error) {
      if(Date.now()>=deadline-250||error?.message==='BACKUP_CHUNK_DEADLINE')throw new Error('BACKUP_CHUNK_DEADLINE');
      lastError = error;
      if (String(options.method||'GET').toUpperCase()!=='GET'||attempt === DRIVE_RETRY_ATTEMPTS - 1) throw error;
      await sleep(400 * (2 ** attempt));
    }
  }
  if (lastResponse) return lastResponse;
  throw lastError || new Error('No se pudo contactar con Google Drive.');
}

async function driveGet(url, token) {
  return driveFetch(url, { headers: { Authorization: `Bearer ${token}` } });
}

async function getDriveUserEmail(token) {
  try {
    const res = await driveGet(`${DRIVE_API}/about?fields=user`, token);
    if (!res.ok) return null;
    const data = await res.json();
    return data.user?.emailAddress || null;
  } catch(error) { if(error?.message==='BACKUP_CHUNK_DEADLINE')throw error;return null; }
}

async function findOrCreateFolder(name, parentId, token) {
  if(parentId)await assertPrivateDriveDestination(parentId,token);
  const escaped = name.replace(/'/g, "\\'");
  let query = `name='${escaped}' and mimeType='application/vnd.google-apps.folder' and trashed=false`;
  if (parentId) query += ` and '${parentId}' in parents`;
  const searchRes = await driveGet(`${DRIVE_API}/files?q=${encodeURIComponent(query)}&orderBy=createdTime&fields=files(id,name,createdTime)`, token);
  if (!searchRes.ok) throw new Error(`No se pudo buscar la carpeta \"${name}\": ${searchRes.status}`);
  const found = await searchRes.json();
  if (found.files?.length > 0) return found.files[0];
  const body = { name, mimeType: 'application/vnd.google-apps.folder' };
  if (parentId) body.parents = [parentId];
  const createRes = await driveFetch(`${DRIVE_API}/files?fields=id,name`, {
    method: 'POST',
    headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
  if (!createRes.ok) throw new Error(`No se pudo crear carpeta "${name}": ${createRes.status}`);
  return await createRes.json();
}

// Folder cache to avoid redundant Drive API calls during backup
const folderCache = new Map();
async function findOrCreateFolderCached(name, parentId, token) {
  const key = `${parentId || 'root'}:${name}`;
  if (folderCache.has(key)) return folderCache.get(key);
  const promise = findOrCreateFolder(name, parentId, token);
  folderCache.set(key, promise);
  try {
    return await promise;
  } catch (e) {
    folderCache.delete(key);
    throw e;
  }
}

const privateDestinations=new Set();
async function assertPrivateDriveDestination(id,token){
 if(!id||privateDestinations.has(id))return;
 let pageToken='';do{
  const response=await driveGet(DRIVE_API+'/files/'+encodeURIComponent(id)+'/permissions?fields=permissions(type,emailAddress,role,deleted),nextPageToken&pageSize=100'+(pageToken?'&pageToken='+encodeURIComponent(pageToken):''),token);
  if(!response.ok)throw new Error('BACKUP_DRIVE_PRIVACY_UNVERIFIED');const data=await response.json();
  if(!Array.isArray(data.permissions)||!data.permissions.length||data.permissions.some(p=>!p.deleted&&(p.type!=='user'||String(p.emailAddress||'').toLowerCase()!==REQUIRED_EMAIL)))throw new Error('BACKUP_DRIVE_SHARED_DESTINATION');
  pageToken=data.nextPageToken||'';
 }while(pageToken);privateDestinations.add(id);
}
async function uploadFileToDrive(name, parentId, contentBytes, mimeType, token) {
  await assertPrivateDriveDestination(parentId,token);
  const boundary = 'taxea_backup_' + Math.random().toString(36).slice(2);
  const checksum=await computeChecksum(contentBytes);
  const backupKey=await computeChecksum(new TextEncoder().encode((parentId||'')+'|'+name+'|'+checksum));
  const query="trashed=false and appProperties has { key='taxeaBackupKey' and value='"+backupKey+"' }";
  const existing=await driveGet(DRIVE_API+'/files?q='+encodeURIComponent(query)+'&fields=files(id,size,name,appProperties)&orderBy=createdTime&pageSize=2',token);
  if(!existing.ok)throw new Error('BACKUP_DRIVE_LOOKUP_HTTP_'+existing.status);
  const previous=(await existing.json()).files?.find(file=>file.appProperties?.taxeaSha256===checksum&&Number(file.size)===contentBytes.length);
  if(previous){await assertPrivateDriveDestination(previous.id,token);const restored=await driveGet(DRIVE_API+'/files/'+encodeURIComponent(previous.id)+'?alt=media',token);if(!restored.ok||await computeChecksum(new Uint8Array(await restored.arrayBuffer()))!==checksum)throw new Error('BACKUP_EXISTING_COPY_HASH_MISMATCH');return previous;}
  const metadata = JSON.stringify({ name, parents: parentId ? [parentId] : [],appProperties:{taxeaBackupKey:backupKey,taxeaSha256:checksum} });
  const encoder = new TextEncoder();
  const header = encoder.encode(
    `--${boundary}\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n${metadata}\r\n` +
    `--${boundary}\r\nContent-Type: ${mimeType}\r\n\r\n`
  );
  const footer = encoder.encode(`\r\n--${boundary}--`);
  const fullBody = new Uint8Array(header.length + contentBytes.length + footer.length);
  fullBody.set(header, 0);
  fullBody.set(contentBytes, header.length);
  fullBody.set(footer, header.length + contentBytes.length);
  const res = await driveFetch(`${DRIVE_UPLOAD}/files?uploadType=multipart&fields=id,size,name`, {
    method: 'POST',
    headers: { Authorization: `Bearer ${token}`, 'Content-Type': `multipart/related; boundary=${boundary}` },
    body: fullBody,
  });
  if (!res.ok) {
    throw new Error(`BACKUP_DRIVE_UPLOAD_HTTP_${res.status}`);
  }
  const uploaded=await res.json();
  const restored=await driveGet(DRIVE_API+'/files/'+encodeURIComponent(uploaded.id)+'?alt=media',token);
  if(!restored.ok||await computeChecksum(new Uint8Array(await restored.arrayBuffer()))!==checksum)throw new Error('BACKUP_UPLOADED_COPY_HASH_MISMATCH');
  return uploaded;
}

