    if(action!=='status'&&!driveEmail)return Response.json({error:'No se pudo verificar la conexión con Google Drive. Reintenta.',code:'DRIVE_CONNECTION_UNVERIFIED'},{status:503});
    if (action !== 'status' && driveEmail !== REQUIRED_EMAIL) {
      return Response.json({
        error: `La copia requiere Google Drive conectado como ${REQUIRED_EMAIL}.`,
        connectedEmail: driveEmail,
        requiredEmail: REQUIRED_EMAIL,
      }, { status: 409 });
    }

    if (action === 'cleanup_failed_backups') {
      if (body.confirmation !== FAILED_BACKUP_CLEANUP_CONFIRMATION) {
        return Response.json({ error: 'Confirmación de limpieza no válida.' }, { status: 400 });
      }
      const folders = await trashExactFailedBackupFolders(accessToken);
      return Response.json({
        ok: true,
        cleanupMode: 'drive_trash_recoverable',
        baselineDate: '2026-08-09',
        folders,
      });
    }

    // Load config
    let configs = await base44.asServiceRole.entities.BackupConfiguration.list();
    let config = configs?.[0];
    if (!config) {
      config = await base44.asServiceRole.entities.BackupConfiguration.create({
        backupMode: 'incremental_with_daily_manifest',
        scheduleEnabled: true,
        scheduleTime: '03:00',
        timezone: 'Atlantic/Canary',
        driveConnectedAccountEmail: driveEmail,
        retentionPolicy: 'indefinite_until_manual_policy',
        folderNamingMode: 'both',
        rootFolderName: 'Taxea Strategies - Backups',
        portalFolderName: 'Taxea Portal',
        lastBackupStatus: 'never',
      });
    }

    if(action!=='status'){
      leaseEntity=base44.asServiceRole.entities.BackupConfiguration;
      lease=await acquireBackupLease(leaseEntity,config.id);
      if(!lease)return Response.json({error:'Ya hay una copia o verificación en curso. Espera y reintenta.',code:'BACKUP_BUSY'},{status:409});
    }
    // ── STATUS action ──
    if (action === 'status') {
      const [recentJobs, allRecords] = await Promise.all([
        base44.asServiceRole.entities.BackupJob.list('-startedAt', 20),
        listAllEntity(base44.asServiceRole.entities.DocumentBackupRecord, '-updated_date', 10000),
      ]);
      const canonicalRecords = Object.values(latestBackupRecordMap(allRecords));
      return Response.json({
        connected: !!driveEmail,
        connectedEmail: driveEmail,
        isCorrectAccount: driveEmail === REQUIRED_EMAIL,
        requiredEmail: REQUIRED_EMAIL,
        config,
        recentJobs: (recentJobs || []).filter(item=>String(item.scopeCompanyId||'')===scopeCompanyId),
        pendingCount: canonicalRecords.filter(record => record.backupStatus === 'pending').length,
        failedCount: canonicalRecords.filter(record => record.backupStatus === 'failed').length,
        trackedDocuments: canonicalRecords.length,
        metadataDuplicateCount: Math.max(0, allRecords.length - canonicalRecords.length),
      });
    }

    // ── VERIFY action: verify the whole manifest, including skipped documents ──
    if (action === 'verify') {
      const recentCompleted = await base44.asServiceRole.entities.BackupJob.list('-startedAt', 50);
      const lastJob = recentCompleted?.find(item => String(item.scopeCompanyId||'')===scopeCompanyId && ['completed', 'completed_with_errors'].includes(item.status) && item.manifestDriveFileId);
      if (!lastJob) return Response.json({ error: 'No hay copias finalizadas con manifiesto para verificar' }, { status: 404 });

      const restart = body.restartVerification === true;
      if (!restart && ['ok', 'incidents'].includes(lastJob.verificationStatus)) {
        return Response.json({
          jobId: lastJob.id, status: lastJob.verificationStatus,
          checked: Number(lastJob.verificationChecked || 0),
          verified: Number(lastJob.documentsVerified || 0),
          missing: Number(lastJob.verificationMissing || 0),
          checksumChecked: Number(lastJob.verificationChecksumChecked || 0),
          issues: lastJob.verificationIssues || [], remaining: 0,
        });
      }

      const manifestRes = await driveGet(`${DRIVE_API}/files/${encodeURIComponent(lastJob.manifestDriveFileId)}?alt=media`, accessToken);
      if (!manifestRes.ok) return Response.json({ error: `No se pudo recuperar el manifiesto de Drive (${manifestRes.status})` }, { status: 503 });
      const manifestBytes = new Uint8Array(await manifestRes.arrayBuffer());
      const manifestChecksum = await computeChecksum(manifestBytes);
      if (!lastJob.manifestChecksum || manifestChecksum !== lastJob.manifestChecksum) {
        await base44.asServiceRole.entities.BackupJob.update(lastJob.id, {
          verificationStatus: 'incidents', verificationIssues: [{ code: 'MANIFEST_CHECKSUM_MISMATCH' }],
        });
        return Response.json({ jobId: lastJob.id, status: 'incidents', error: 'El hash del manifiesto no coincide. La copia no está verificada.' }, { status: 409 });
      }

      let manifest;
      try { manifest = JSON.parse(new TextDecoder().decode(manifestBytes)); }
      catch { return Response.json({ error: 'El manifiesto no es JSON válido.' }, { status: 409 }); }
      const entries = manifest?.documents;
      if (!Array.isArray(entries) || Number(manifest.totalDocuments) !== entries.length
        || Number(lastJob.documentsScanned) !== entries.length) {
        return Response.json({ error: 'El número de documentos del manifiesto no coincide con el trabajo.' }, { status: 409 });
      }

      const cursor = restart ? 0 : Math.min(Math.max(0, Number(lastJob.verificationChecked || 0)), entries.length);
      const verifiedBefore = restart ? 0 : Number(lastJob.documentsVerified || 0);
      const missingBefore = restart ? 0 : Number(lastJob.verificationMissing || 0);
      const checksumBefore = restart ? 0 : Number(lastJob.verificationChecksumChecked || 0);
      const issuesBefore = restart ? [] : (lastJob.verificationIssues || []);
      const lastCopiedIndex = entries.findLastIndex(entry => entry.status === 'backed_up' && entry.driveFileId);
      const sampleIndices = new Set([0, Math.floor(entries.length / 2), entries.length - 1, lastCopiedIndex]);
      const batch = entries.slice(cursor, cursor + 25);
      const results = [];
      for (let offset = 0; offset < batch.length; offset += 5) {
        if(results.length&&Date.now()>deadline-10000)break;
        const group = batch.slice(offset, offset + 5);
        const groupResults = await Promise.all(group.map(async (entry, localIndex) => {
          const index = cursor + offset + localIndex;
          if (!entry.driveFileId || !entry.checksum) return { ok: false, code: 'MISSING_COPY_OR_HASH', index };
          const metaRes = await driveGet(`${DRIVE_API}/files/${encodeURIComponent(entry.driveFileId)}?fields=id,size,trashed`, accessToken);
          if (metaRes.status === 404) return { ok: false, code: 'DRIVE_FILE_MISSING', index };
          if (!metaRes.ok) throw new Error(`Drive metadata verification failed (${metaRes.status})`);
          const metadata = await metaRes.json();
          if (metadata.trashed || metadata.id !== entry.driveFileId) return { ok: false, code: 'DRIVE_FILE_UNAVAILABLE', index };
          if (Number(metadata.size) !== Number(entry.size)) return { ok: false, code: 'SIZE_MISMATCH', index };
          if(Number(entry.size)>MAX_BACKUP_FILE_BYTES)return {ok:false,code:'COPY_TOO_LARGE_TO_VERIFY',index};
          const contentRes = await driveGet(`${DRIVE_API}/files/${encodeURIComponent(entry.driveFileId)}?alt=media`, accessToken);
          if (contentRes.status === 404) return { ok: false, code: 'DRIVE_FILE_MISSING', index };
          if (!contentRes.ok) throw new Error(`Drive content verification failed (${contentRes.status})`);
          const restoredBytes = new Uint8Array(await contentRes.arrayBuffer());
          if (await computeChecksum(restoredBytes) !== entry.checksum) return { ok: false, code: 'CONTENT_CHECKSUM_MISMATCH', index };
          return { ok: true, checksumChecked: true, index };
        }));
        results.push(...groupResults);
      }

      const checked = cursor + results.length;
      const verified = verifiedBefore + results.filter(result => result.ok).length;
      const missing = missingBefore + results.filter(result => !result.ok).length;
      const checksumChecked = checksumBefore + results.filter(result => result.checksumChecked).length;
      const issues = [...issuesBefore, ...results.filter(result => !result.ok).map(result => ({
        code: result.code, manifestIndex: result.index,
      }))].slice(0, 20);
      const remaining = entries.length - checked;
      if (remaining === 0 && entries.length > 0 && checksumChecked === 0) {
        issues.push({ code: 'NO_CONTENT_SAMPLE' });
      }
      if (remaining === 0 && (lastJob.status === 'completed_with_errors' || Number(lastJob.documentsFailed || 0) > 0)) {
        issues.push({ code: 'BACKUP_RUN_ERRORS' });
      }
      const status = remaining > 0 ? 'partial' : (missing === 0 && issues.length === 0 && (entries.length === 0 || checksumChecked > 0) ? 'ok' : 'incidents');
      await base44.asServiceRole.entities.BackupJob.update(lastJob.id, {
        verificationChecked: checked, documentsVerified: verified,
        verificationMissing: missing, verificationChecksumChecked: checksumChecked,
        verificationStatus: status, verificationIssues: issues.slice(0, 20),
        ...(status === 'ok' ? { lastVerifiedAt: new Date().toISOString() } : {}),
      });
      return Response.json({
        jobId: lastJob.id, status, checked, verified, missing, checksumChecked,
        issues: issues.slice(0, 20), remaining, total: entries.length,
      });
    }

    // ── BACKUP action ──
    const now = getCanaryDate();
    const requestedJobId = String(body.resumeJobId || '').trim();
    let job = requestedJobId ? await base44.asServiceRole.entities.BackupJob.get(requestedJobId).catch(() => null) : null;
    const requestedJobType = isManual ? 'manual' : 'scheduled';
    if (job && (!['preparing', 'copying'].includes(job.status) || String(job.scopeCompanyId||'')!==scopeCompanyId)) job = null;
    if (!job) {
      const recentJobs = (await base44.asServiceRole.entities.BackupJob.list('-startedAt', 50)).filter(item=>String(item.scopeCompanyId||'')===scopeCompanyId);
      const nowMs = Date.now();
      const maxJobAge = item => item.jobType === 'scheduled' ? SCHEDULED_JOB_MAX_AGE_MS : MANUAL_JOB_MAX_AGE_MS;
      job = recentJobs?.find(item =>
        ['preparing', 'copying'].includes(item.status) &&
        nowMs - new Date(item.lastHeartbeatAt || item.startedAt || 0).getTime() < maxJobAge(item)
      ) || null;
      for (const stale of recentJobs || []) {
        if (!['preparing', 'copying'].includes(stale.status)) continue;
        if (nowMs - new Date(stale.lastHeartbeatAt || stale.startedAt || 0).getTime() < maxJobAge(stale)) continue;
        await base44.asServiceRole.entities.BackupJob.update(stale.id, {
          status: 'failed', completedAt: new Date().toISOString(), internalErrorCode: 'STALE_INTERRUPTED',
          safeErrorMessage: 'Ejecución interrumpida; puede iniciarse una nueva copia sin duplicar documentos.',
        }).catch(() => {});
      }
    }
    if (!job) {
      job = await base44.asServiceRole.entities.BackupJob.create({
        jobType: isManual ? 'manual' : 'scheduled',
        status: 'preparing',
        startedAt: new Date().toISOString(),
        lastHeartbeatAt: new Date().toISOString(),
        triggeredByUserId: user?.id || null,
        triggeredByEmail: user?.email || 'sistema',
        driveAccountEmail: driveEmail,
        backupMode: config.backupMode,
        nextCursor: 0,
        runVersion: 'snapshot-v4',
        scopeCompanyId,
        documentsScanned: 0, documentsCopied: 0, documentsSkipped: 0, documentsFailed: 0, bytesCopied: 0,
      });
    }

    try {
      // Update config with connected email
      if (driveEmail && config.driveConnectedAccountEmail !== driveEmail) {
        config = await base44.asServiceRole.entities.BackupConfiguration.update(config.id, { driveConnectedAccountEmail: driveEmail });
      }

      // QA uses a separate destination and does not change production success markers.
      if(scopeCompanyId)config={...config,portalFolderName:(config.portalFolderName||'Taxea Portal')+' — QA INTERNA'};
      // Ensure folder structure
      const rootFolder = await findOrCreateFolder(config.rootFolderName || 'Taxea Strategies - Backups', null, accessToken);
      const portalFolder = await findOrCreateFolder(config.portalFolderName || 'Taxea Portal', rootFolder.id, accessToken);
      const yearFolder = await findOrCreateFolder(now.year, portalFolder.id, accessToken);
      const monthFolder = await findOrCreateFolder(now.month, yearFolder.id, accessToken);
      const dayFolder = job.driveBackupFolderId
        ? { id: job.driveBackupFolderId, name: now.full }
        : await findOrCreateFolder(now.full, monthFolder.id, accessToken);

      await base44.asServiceRole.entities.BackupJob.update(job.id, {
        status: 'copying',
        lastHeartbeatAt: new Date().toISOString(),
        driveRootFolderId: rootFolder.id,
        driveBackupFolderId: dayFolder.id,
        driveBackupFolderPath: `${config.rootFolderName}/${config.portalFolderName}/${now.year}/${now.month}/${now.full}`,
      });
      if(!scopeCompanyId)await base44.asServiceRole.entities.BackupConfiguration.update(config.id, { lastBackupStatus: 'running' });

      // Load the complete history and keep one canonical record per source document.
      const resumableManifest=job.runVersion==='snapshot-v4';
      const existingRecords = resumableManifest?[]:await listAllEntity(base44.asServiceRole.entities.DocumentBackupRecord, '-updated_date', 10000);
      const recordMap = latestBackupRecordMap(existingRecords);

      const companyCache = {};
      const isFullCopy = config.backupMode === 'full_daily_copy';
      let copied = Number(job.documentsCopied || 0);
      let skipped = Number(job.documentsSkipped || 0);
      let failed = Number(job.documentsFailed || 0);
      let bytesCopied = Number(job.bytesCopied || 0);
      const failedItems = [];

      // Scan all documents
      let documents;
      if(job.sourceIndexDriveFileId){
        const response=await driveGet(DRIVE_API+'/files/'+encodeURIComponent(job.sourceIndexDriveFileId)+'?alt=media',accessToken);
        if(!response.ok)throw new Error('BACKUP_INDEX_UNAVAILABLE');
        const bytes=new Uint8Array(await response.arrayBuffer());
        if(await computeChecksum(bytes)!==job.sourceIndexChecksum)throw new Error('BACKUP_INDEX_HASH_MISMATCH');
        const index=JSON.parse(new TextDecoder().decode(bytes));
        if(index.jobId!==job.id||index.scopeCompanyId!==scopeCompanyId||!Array.isArray(index.documents)||index.documents.length!==job.sourceIndexCount)throw new Error('BACKUP_INDEX_INVALID');
        documents=backupSnapshot(index.documents,DOC_SOURCES);
      }else{
        let state;
        try{state=job.inventoryState?JSON.parse(job.inventoryState):freshInventory(job.id,job.startedAt,scopeCompanyId);}catch{throw new Error('BACKUP_INVENTORY_INVALID');}
        if(state.jobId!==job.id||state.scopeCompanyId!==scopeCompanyId)throw new Error('BACKUP_INVENTORY_SCOPE_MISMATCH');
        const resolveCompany=createBackupContextResolver(base44.asServiceRole);
        state=await advanceDocumentInventory({service:base44.asServiceRole,state,resolveCompany,deadline,
         uploadPage:async page=>{const content=JSON.stringify({...page,documents:backupSnapshot(page.documents,DOC_SOURCES)}),bytes=new TextEncoder().encode(content);const saved=await uploadTextFile('inventory_'+job.id+'_'+page.index+'.json',dayFolder.id,content,accessToken);return{id:saved.id,sha256:await computeChecksum(bytes)};},
         persist:async current=>{const patch={inventoryState:JSON.stringify(current),documentsScanned:current.count,lastHeartbeatAt:new Date().toISOString()};await base44.asServiceRole.entities.BackupJob.update(job.id,patch);job={...job,...patch};}
        });
        if(!state.done)return Response.json({status:'copying',phase:'inventory',jobId:job.id,continueRequired:true,documentsScanned:state.count,documentsProcessed:0,inventorySourcesCompleted:state.source,inventorySourcesTotal:BACKUP_DOCUMENT_SOURCES.length,retryAfterSeconds:1},{status:202});
        documents=backupSnapshot(await loadInventoryDocuments(state,async id=>{const response=await driveGet(DRIVE_API+'/files/'+encodeURIComponent(id)+'?alt=media',accessToken);if(!response.ok)throw new Error('BACKUP_INVENTORY_PART_UNAVAILABLE');return new Uint8Array(await response.arrayBuffer());},computeChecksum),DOC_SOURCES);
        const sourceIndex=JSON.stringify({version:4,jobId:job.id,scopeCompanyId,cutoff:state.cutoff,unassigned:state.unassigned,excludedExternal:state.excludedExternal,documents});
        const uploadedIndex=await uploadTextFile('source_index_'+job.id+'.json',dayFolder.id,sourceIndex,accessToken);
        const patch={sourceIndexDriveFileId:uploadedIndex.id,sourceIndexChecksum:await computeChecksum(new TextEncoder().encode(sourceIndex)),sourceIndexCount:documents.length,...(!['snapshot-v3','snapshot-v4'].includes(job.runVersion)?{nextCursor:0,documentsCopied:0,documentsSkipped:0,documentsFailed:0,bytesCopied:0,runVersion:'snapshot-v3'}:{})};
        await base44.asServiceRole.entities.BackupJob.update(job.id,patch);job={...job,...patch};
      }
      const startCursor = Math.min(Math.max(0, Number(job.nextCursor || 0)), documents.length);
      await base44.asServiceRole.entities.BackupJob.update(job.id, {
        documentsScanned: documents.length,
        lastHeartbeatAt: new Date().toISOString(),
      });

      copied=Number(job.documentsCopied||0);skipped=Number(job.documentsSkipped||0);failed=Number(job.documentsFailed||0);bytesCopied=Number(job.bytesCopied||0);
      // Per-document processing (extracted for parallel batching)
      const processDoc = async ({ record, source }) => {
        const fileUrl = record[source.urlField];
        const docId = record.id;
        const key = `${source.entity}:${docId}`;
        if(resumableManifest&&!recordMap[key]){const matches=await base44.asServiceRole.entities.DocumentBackupRecord.filter({documentEntity:source.entity,documentId:docId},'-updated_date',20);recordMap[key]=latestBackupRecordMap(matches)[key]||null;}
        const existing = recordMap[key];
        const sourceUnchanged = !existing?.fileStorageUrl || existing.fileStorageUrl === fileUrl;
        const skipExisting = !isFullCopy && existing && ['backed_up', 'verified'].includes(existing.backupStatus) && !!existing.driveFileId && !!existing.checksum && sourceUnchanged;

        const companyName = await getCompanyName(record[source.companyField], base44, companyCache);
        const subfolder = getSubfolder(source.entity, record);
        const displayName = getDisplayName(source.entity, record,source);
        const safeFileName = sanitizeName(displayName) || sanitizeName(fileUrl.split('/').pop() || 'documento');
        const mimeType = guessMimeType(displayName, source.mimeField ? record[source.mimeField] : null);

        if (skipExisting) {
          return { type: 'skipped', manifest: {
            documentId: docId, documentEntity: source.entity,
            clientAccountId: record[source.companyField], clientName: companyName,
            type: source.entity, originalFileName: displayName,
            size: existing.fileSize || (source.sizeField ? record[source.sizeField] : 0),
            mimeType, checksum: existing?.checksum || '',
            driveFileId: existing?.driveFileId || '', drivePath: existing?.drivePath || '',
            status: 'skipped_existing', lastVerifiedAt: existing?.lastVerifiedAt || '',
          }};
        }

        // Download file from storage
        let contentBytes;
        try {
          contentBytes = await downloadBackupFile(fileUrl,base44,user,record[source.companyField],deadline);
        } catch (e) {
          if(Date.now()>=deadline-250||e?.message==='BACKUP_CHUNK_DEADLINE')throw new Error('BACKUP_CHUNK_DEADLINE');
          await base44.asServiceRole.entities.BackupJobItem.create({
            backupJobId: job.id, documentId: docId, documentEntity: source.entity,
            clientAccountId: record[source.companyField], clientName: companyName,
            status: 'failed', action: 'fail', safeErrorMessage: `download: ${e.message}`, attempts: 1,
          });
          if (existing) {
            await base44.asServiceRole.entities.DocumentBackupRecord.update(existing.id, { ...(existing.driveFileId&&existing.checksum?{}:{backupStatus:'failed'}),safeErrorMessage:'BACKUP_DOWNLOAD_FAILED' });
          }
          return { type: 'failed', docId, error: `download: ${e.message}` };
        }

        const checksum = await computeChecksum(contentBytes);
        const fileSize = contentBytes.length;

        // If the URL changed but the bytes did not, refresh metadata without creating another Drive copy.
        if (!isFullCopy && existing && ['backed_up', 'verified'].includes(existing.backupStatus) && existing.driveFileId && existing.checksum === checksum) {
          const nowIso = new Date().toISOString();
          const refreshed = await base44.asServiceRole.entities.DocumentBackupRecord.update(existing.id, {
            backupStatus: 'backed_up', originalFileName: displayName, fileStorageUrl: fileUrl,
            fileSize, mimeType, safeErrorMessage: '',
          });
          recordMap[key] = { ...existing, ...refreshed, fileStorageUrl: fileUrl };
          return { type: 'skipped', manifest: {
            documentId: docId, documentEntity: source.entity,
            clientAccountId: record[source.companyField], clientName: companyName,
            type: source.entity, originalFileName: displayName, size: fileSize,
            mimeType, checksum, driveFileId: existing.driveFileId, drivePath: existing.drivePath,
            status: 'skipped_unchanged', lastVerifiedAt: existing.lastVerifiedAt || '',
          }};
        }

        // Folder creation and upload are one recoverable operation. Drive throttling is retried by driveFetch.
        try {
          const cFolderName = clientFolderName(record[source.companyField], companyName, config.folderNamingMode);
          const clientFolder = await findOrCreateFolderCached(cFolderName, dayFolder.id, accessToken);
          const subFolder = await findOrCreateFolderCached(subfolder, clientFolder.id, accessToken);
          const drivePath = `${now.full}/${cFolderName}/${subfolder}/${safeFileName}`;
          const uploaded = await uploadFileToDrive(safeFileName, subFolder.id, contentBytes, mimeType, accessToken);
          const nowIso = new Date().toISOString();
          let persisted;
          if (existing) {
            persisted = await base44.asServiceRole.entities.DocumentBackupRecord.update(existing.id, {
              backupStatus: 'backed_up', originalFileName: displayName, fileStorageUrl: fileUrl,
              driveFileId: uploaded.id, driveFolderId: subFolder.id,
              drivePath, checksum, fileSize, mimeType, lastBackedUpAt: nowIso,
              version: (existing.version || 1) + 1, safeErrorMessage: '',
            });
          } else {
            persisted = await base44.asServiceRole.entities.DocumentBackupRecord.create({
              documentId: docId, documentEntity: source.entity,
              clientAccountId: record[source.companyField], clientName: companyName,
              documentType: source.entity, sourceModule: subfolder,
              originalFileName: displayName, fileStorageUrl: fileUrl,
              fileSize, mimeType, checksum,
              driveFileId: uploaded.id, driveFolderId: subFolder.id, drivePath,
              backupStatus: 'backed_up', lastBackedUpAt: nowIso, version: 1,
            });
          }
          recordMap[key] = persisted;
          await base44.asServiceRole.entities.BackupJobItem.create({
            backupJobId: job.id, documentId: docId, documentEntity: source.entity,
            clientAccountId: record[source.companyField], clientName: companyName,
            status: 'copied', action: 'copy', driveFileId: uploaded.id, drivePath, checksum, fileSize,
          });
          return { type: 'copied', fileSize, manifest: {
            documentId: docId, documentEntity: source.entity,
            clientAccountId: record[source.companyField], clientName: companyName,
            type: source.entity, originalFileName: displayName, size: fileSize,
            mimeType, checksum, driveFileId: uploaded.id, drivePath,
            status: 'copied', lastVerifiedAt: nowIso,
          }};
        } catch (e) {
          if(Date.now()>=deadline-250||e?.message==='BACKUP_CHUNK_DEADLINE')throw new Error('BACKUP_CHUNK_DEADLINE');
          await base44.asServiceRole.entities.BackupJobItem.create({
            backupJobId: job.id, documentId: docId, documentEntity: source.entity,
            clientAccountId: record[source.companyField], clientName: companyName,
            status: 'failed', action: 'fail', safeErrorMessage: `upload: ${e.message}`, attempts: DRIVE_RETRY_ATTEMPTS,
          });
          if (existing) {
            const failedRecord = await base44.asServiceRole.entities.DocumentBackupRecord.update(existing.id, {
              ...(existing.driveFileId&&existing.checksum?{}:{backupStatus:'failed'}),safeErrorMessage:'BACKUP_UPLOAD_FAILED',
            });
            recordMap[key] = { ...existing, ...failedRecord };
          }
          return { type: 'failed', docId, error: `upload: ${e.message}` };
        }
      };

      // Process a bounded chunk and persist the cursor. Manual runs continue through short requests
      // instead of keeping one request open for four minutes.

      let nextCursor = startCursor;
      let copyManifestParts=job.copyManifestParts?JSON.parse(job.copyManifestParts):[];
      if(!Array.isArray(copyManifestParts))throw new Error('BACKUP_MANIFEST_PARTS_INVALID');

      for (let i = startCursor; i < documents.length; i += BACKUP_BATCH_SIZE) {
        if (Date.now() - invocationStartedAt >= timeBudgetMs) break;
        const batch = documents.slice(i, i + BACKUP_BATCH_SIZE);
        const results = await Promise.allSettled(batch.map(doc => processDoc(doc)));
        if(results.some(result=>result.status==='rejected'&&result.reason?.message==='BACKUP_CHUNK_DEADLINE'))break;
        for (const result of results) {
          if (result.status === 'fulfilled') {
            const item = result.value;
            if (item.type === 'copied') { copied++; bytesCopied += item.fileSize; }
            else if (item.type === 'skipped') skipped++;
            else if (item.type === 'failed') {
              failed++;
              failedItems.push({ documentId: item.docId, error: item.error });
            }
          } else {
            failed++;
            failedItems.push({ documentId: 'unknown', error: result.reason?.message || 'Error no identificado' });
          }
        }
        if(resumableManifest){
         const partEntries=[];
      for (const { record, source } of batch) {
        const backupRecord = recordMap[`${source.entity}:${record.id}`];
